static byte[] RenderScore(int score)
{
    using var surface = SKSurface.Create(new SKImageInfo(640, 120));
    using var paint = new SKPaint { TextSize = 48 };
    surface.Canvas.Clear(SKColors.White);
    surface.Canvas.DrawText(score.ToString(), 16, 72, paint);
    using var image = surface.Snapshot();
    using var data = image.Encode(SKEncodedImageFormat.Png, 80);
    return data.ToArray();
}

static async Task DrainAsync(IAsyncDisposable session)
{
    await using (session.ConfigureAwait(false))
    {
        await Task.CompletedTask;
    }
}
